/* Chemistry Atlas complete course. Original learning content; authentic IB resources are external. */
'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
const safeURL=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}};
const KEY='chemistry-atlas-full-v1';let stored={};try{stored=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const progress={level:stored.level==='SL'?'SL':'HL',done:stored.done||{},results:stored.results||{},stars:stored.stars||{},drafts:stored.drafts||{},tests:stored.tests||[],activeTest:stored.activeTest||null};
const state={page:'home',id:'',search:'',filters:{topic:'all',level:'all',paper:'all',difficulty:'all',status:'all'},limit:18,revealed:{},chosen:{},session:null,cloudReady:false,tutorContext:'',messages:[],testSelection:[],testTarget:70};
const LESSONS=COURSE.flatMap(t=>t.sections),byTopic=id=>COURSE.find(t=>t.id===id),byLesson=id=>LESSONS.find(s=>s.id===id),byQ=id=>QUESTIONS.find(q=>q.id===id);
const visible=s=>progress.level==='HL'||!s.hl;
const topics=()=>COURSE.filter(t=>t.sections.some(visible));
const lessons=()=>LESSONS.filter(visible);
const questions=()=>QUESTIONS.filter(q=>progress.level==='HL'||q.level!=='HL');
const completed=()=>lessons().filter(s=>progress.done[s.id]).length;
const topicPct=t=>{const a=t.sections.filter(visible);return a.length?Math.round(a.filter(s=>progress.done[s.id]).length/a.length*100):0};
const bars=p=>`<div class="progressbar"><span style="width:${Math.min(100,Math.max(0,p))}%"></span></div>`;
const pill=(s,c='')=>`<span class="pill ${c}">${esc(s)}</span>`;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(progress))}catch{toast('Browser storage is unavailable. Export your progress before leaving.')}}
const crumb=(p=[])=>`<div class="breadcrumb"><a href="#home">Chemistry ${progress.level}</a>${p.map(x=>`<span>›</span>${typeof x==='string'?`<span>${esc(x)}</span>`:`<a href="${x.href}">${esc(x.title)}</a>`}`).join('')}</div>`;
function head(k,h,p){return `${crumb([h])}<span class="eyebrow">${esc(k)}</span><h1>${esc(h)}</h1><p class="lede">${p}</p>`}
function iconMolecule(){return `<svg viewBox="0 0 480 390" aria-hidden="true"><circle cx="285" cy="180" r="155" fill="none" stroke="#8cc2b633"/><circle cx="285" cy="180" r="200" fill="none" stroke="#8cc2b622"/><path d="M160 202L276 97L373 192L281 296L160 202" fill="none" stroke="#7ba59f" stroke-width="10"/><path d="M276 97L281 296M160 202L373 192" stroke="#749d9633" stroke-width="3"/><circle cx="160" cy="202" r="36" fill="#b5d8c7"/><circle cx="276" cy="97" r="47" fill="#94b9ae"/><circle cx="373" cy="192" r="31" fill="#e5ba92"/><circle cx="281" cy="296" r="45" fill="#85b7b4"/><circle cx="150" cy="190" r="9" fill="#ecf6e8" opacity=".65"/><circle cx="262" cy="81" r="13" fill="#daeee2" opacity=".5"/><circle cx="273" cy="283" r="10" fill="#d7f2e9" opacity=".5"/><path d="M411 54v23M400 66h23M93 106v16M85 114h16" stroke="#afd6c8" stroke-width="2"/></svg>`}
function navUI(){const groups=[...new Set(topics().map(t=>t.group))];$('#topicNav').innerHTML=groups.map((g,i)=>`<div class="nav-group">${esc(g)}</div>${topics().filter(t=>t.group===g).map(t=>`<a href="#topic/${t.id}" class="nav-topic ${state.id.startsWith(t.id)&&['topic','lesson'].includes(state.page)?'active':''}"><small>${t.id}</small><span>${esc(t.name)}</span></a>`).join('')}`).join('');$$('.main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===state.page||(a.dataset.route==='syllabus'&&['topic','lesson'].includes(state.page))));$('#level').value=progress.level;$('#accountBtn').textContent=state.session?'My account ✓':'Sign in ↗'}
function groupCards(){const groups=[...new Set(topics().map(t=>t.group))];return `<div class="course-grid">${groups.map((g,i)=>`<section class="card group-card"><div class="group-heading"><span class="group-icon">${['◈','⌘','▦','ϟ','◴','↔'][i]}</span><div><h3>${esc(g)}</h3><small>${esc(GROUP_NAMES[g]||'')}${progress.level==='SL'&&g==='Reactivity 1'?' · Entropy is HL only':''}</small></div></div>${topics().filter(t=>t.group===g).map(t=>`<a class="group-topic" href="#topic/${t.id}"><span class="topic-number">${t.id}</span><span>${esc(t.name)}</span><span class="topic-count">${t.sections.filter(visible).length} lessons</span><span class="arrow">→</span></a>`).join('')}</section>`).join('')}</div>`}
function home(){const pct=Math.round(completed()/lessons().length*100);return `${crumb(['Your study space'])}<section class="hero"><div class="hero-copy"><span class="eyebrow">A CLEARER PATH THROUGH IB CHEMISTRY</span><h1>Learn the <em>why.</em><br>Then master the how.</h1><p>Your complete ${progress.level} syllabus, made easier to understand.<br>Illustrated notes, worked examples, video lessons and focused practice—one concept at a time.</p><div class="row"><a class="btn light" href="#syllabus">Explore your syllabus ↗</a><a class="btn outline-light" href="#test">Build a target test →</a></div></div><div class="hero-art">${iconMolecule()}</div></section><div class="grid"><div class="card stat"><span class="stat-icon">▤</span><div><strong>${lessons().length}</strong><small>SYLLABUS LEARNING OUTCOMES</small></div></div><div class="card stat"><span class="stat-icon">▦</span><div><strong>${questions().length}</strong><small>ORIGINAL PRACTICE QUESTIONS</small></div></div><div class="card stat"><span class="stat-icon">◔</span><div><strong>${pct}%</strong><small>OF YOUR COURSE REVIEWED</small></div></div></div><div class="section-head"><div><h2>Your course, from start to finish.</h2><p>${progress.level==='HL'?'Shared SL content and HL extensions, clearly marked.':'Shared SL outcomes only. Switch level in the sidebar to see HL extensions.'}</p></div><a href="#progress">View progress ↗</a></div>${groupCards()}<div class="notice"><strong>Built from your uploaded syllabus.</strong> All 165 numbered outcomes are mapped across 22 topics, plus the guide’s practical and inquiry skills. Explanations and examples are original teaching material. The question bank contains independent exam-style practice; genuine IB papers and official mark schemes are linked separately.</div>`}
function syllabus(){return `${head('THE COMPLETE COURSE','Revision notes',`Follow the uploaded Chemistry Guide, first assessment 2025. Your ${progress.level} course currently shows ${lessons().length} outcomes in ${topics().length} topics. Each lesson includes explanations, a model, a worked example and videos.`)}${groupCards()}<div class="section-head"><h2>Don’t forget the practical skills</h2></div><div class="card panel"><p class="lede">Experimental techniques, data handling, mathematics and inquiry support every chemistry topic and Paper 1B.</p><a class="btn primary" href="#skills">Study the skills hub →</a></div>`}
function topic(){const t=byTopic(state.id);if(!t)return missing();const ss=t.sections.filter(visible);return `${crumb([{title:'Revision notes',href:'#syllabus'},t.id])}<div class="topic-hero"><span class="eyebrow">${esc(t.group)} · ${t.id}</span><h1>${esc(t.name)}</h1><p>${ss.length} ${progress.level} learning outcomes. Learn each idea, follow a worked solution, then practise.</p><div class="row"><a class="btn primary" href="#lesson/${ss[0]?.id||''}">Start reading →</a><a class="btn" href="#bank" data-banktopic="${t.id}">Practice this topic</a><span class="pill soft">${topicPct(t)}% reviewed</span></div>${bars(topicPct(t))}</div><div class="lessons">${ss.map(s=>`<a class="lesson-link" href="#lesson/${s.id}"><span class="lesson-code">${s.id}</span><div style="flex:1"><h3>${esc(s.title)} ${s.hl?pill('HL ONLY','hl'):''}</h3><p>${esc(s.summary)}</p></div><span class="arrow">${progress.done[s.id]?'✓ Studied':'Open lesson →'}</span></a>`).join('')}</div>${topicVideos(t.id)}`}
function list(items){return `<ol>${(items||[]).map(x=>`<li><span>${fmt(x)}</span></li>`).join('')}</ol>`}
function videoCard(v,related=false){return `<a class="video-card" href="${safeURL(v.url)}" target="_blank" rel="noopener noreferrer"><span class="play">▶</span><span><strong>${esc(v.title)}</strong><small>${esc(v.provider)} · ${v.hl?'HL extension':'SL + HL'} · ${v.kind==='collection'?'Lesson collection':'Video lesson'}${related?' · Related topic resource':''}</small><p>${v.kind==='collection'?'Open the creator’s topic page with video lessons.':'Watch the creator’s lesson ↗'}</p></span></a>`}
function topicVideos(id){const vs=VIDEOS.filter(v=>v.topic===id&&(progress.level==='HL'||!v.hl)&&v.kind==='collection');return vs.length?`<div class="section-head"><h2>Watch the topic</h2><p>Creator-hosted video collections</p></div>${vs.map(v=>videoCard(v)).join('')}`:''}
function lesson(){const s=byLesson(state.id);if(!s)return missing();if(!visible(s))return `${head('HL EXTENSION',s.title,'This outcome is part of the Higher Level course. Switch the course selector to HL to open its notes.')}<button class="btn primary" data-action="setHL">Switch to HL</button>`;const t=byTopic(s.id.split('.').slice(0,2).join('.')),all=lessons(),i=all.findIndex(x=>x.id===s.id),vs=VIDEOS.filter(v=>v.outcomes?.includes(s.id)&&(progress.level==='HL'||!v.hl)&&v.kind==='video'),fallback=VIDEOS.filter(v=>v.topic===t.id&&(progress.level==='HL'||!v.hl)&&v.kind==='collection');let renderedVisual=lessonVisual(s).replace('aria-label="Original chemistry concept illustration"',`aria-label="${esc(s.visual.title||s.title)}"`);return `${crumb([{title:'Revision notes',href:'#syllabus'},{title:t.name,href:'#topic/'+t.id},s.id])}<div class="article-layout"><article class="article"><div class="row">${pill(s.id)} ${pill(s.hl?'HL ONLY':'SL + HL',s.hl?'hl':'soft')} ${pill('Guide p. '+s.source.guidePage,'soft')}</div><h1>${esc(s.title)}</h1><p class="intro">${esc(s.summary)}</p><div class="row"><button class="btn ${progress.done[s.id]?'primary':''}" data-action="done" data-id="${s.id}">${progress.done[s.id]?'✓ Marked as studied':'✓ Mark as studied'}</button><button class="btn" data-action="print">Print notes</button><button class="btn" data-asklesson="${s.id}">✦ Ask about this</button></div>
<section class="article-section" id="explanation"><span class="eyebrow">UNDERSTAND THE CONCEPT</span><h2>What it means & how it works</h2>${s.explain.map(p=>`<p>${fmt(p)}</p>`).join('')}${s.formula?`<div class="formula">${esc(s.formula)}</div>`:''}${s.objectives?`<details style="margin-top:18px"><summary style="font-size:11px;color:#85a196;cursor:pointer">Syllabus checklist</summary><ul>${s.objectives.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}</section>
<section class="article-section" id="visual"><span class="eyebrow">MAKE THE CONNECTION</span><h2>The model, made visible</h2><figure>${renderedVisual}<figcaption>Original concept illustration · schematic, not to scale. The diagram supports the topic model; apply the detailed notes to this outcome.</figcaption></figure></section>
<section class="article-section" id="method"><span class="eyebrow">BUILD YOUR METHOD</span><h2>How to approach the question</h2>${list(s.steps)}</section>
<section class="article-section" id="worked"><span class="eyebrow">WORKED EXAMPLE</span><h2>Let’s work through one.</h2><div class="worked"><h3>${esc(s.example.q)}</h3>${list(s.example.steps)}<div class="answer">✓ ${esc(s.example.answer)}</div></div><p class="question-note" style="margin-top:12px;margin-bottom:0">This is an original teaching example, not an official IB past-paper question.</p></section>
<section class="article-section" id="mistake"><h2>A common mistake to avoid</h2><div class="warning"><strong>Watch out for this</strong>${esc(s.mistake)}</div></section>
<section class="article-section" id="videos"><span class="eyebrow">ANOTHER WAY TO LEARN</span><h2>Watch & understand</h2>${vs.length?vs.slice(0,5).map(v=>videoCard(v)).join(''):fallback.slice(0,2).map(v=>videoCard(v,true)).join('')}<p style="font-size:10px;color:#9bafb7;margin-top:13px">Links and lesson associations checked against the creator’s pages on 7 November 2026. Video playback and future availability can vary.</p></section>
<section class="article-section" id="practice"><h2>Put it into practice</h2><p>Try this topic’s original exam-style questions, or ask the tutor to explain a step from this lesson.</p><div class="row"><a class="btn primary" href="#bank" data-banktopic="${t.id}">Practise ${t.id} →</a><button class="btn" data-asklesson="${s.id}">✦ Explain a step</button></div></section>
<div class="lesson-bottom">${i?`<a class="btn" href="#lesson/${all[i-1].id}">← ${all[i-1].id}</a>`:'<span></span>'}<a class="btn" href="#topic/${t.id}">All lessons</a>${i<all.length-1?`<a class="btn primary" href="#lesson/${all[i+1].id}">Next ${all[i+1].id} →</a>`:'<a class="btn primary" href="#test">Build a test →</a>'}</div></article><nav class="card toc sticky" aria-label="Lesson contents"><h3>IN THIS LESSON</h3><a href="#explanation" data-scroll="explanation">The explanation</a><a href="#visual" data-scroll="visual">The visual model</a><a href="#method" data-scroll="method">The method</a><a href="#worked" data-scroll="worked">Worked example</a><a href="#mistake" data-scroll="mistake">Exam mistakes</a><a href="#videos" data-scroll="videos">Watch the lessons</a><a href="#practice" data-scroll="practice">Practice</a><button class="btn primary" data-asklesson="${s.id}">✦ Ask the tutor</button><p style="font-size:9px;color:#a0b2b9;margin:17px 0 0">${s.hl?'HL extension':'Core content for SL and HL'}<br>Original teaching material aligned to ${s.id}.</p></nav></div>`}
function select(name,label,opts,value){return `<div class="field"><label for="filter-${name}">${label}</label><select id="filter-${name}" data-filter="${name}">${opts.map(([v,s])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(s)}</option>`).join('')}</select></div>`}
function pool(){const f=state.filters;return questions().filter(q=>(f.topic==='all'||q.topic===f.topic)&&(f.level==='all'||q.level===f.level)&&(f.paper==='all'||q.paper===f.paper)&&(f.difficulty==='all'||q.difficulty===f.difficulty)&&(f.status==='all'||f.status==='saved'&&progress.stars[q.id]||f.status==='unanswered'&&progress.results[q.id]===undefined||f.status==='review'&&progress.results[q.id]?.score<q.marks));}
function solution(q){return `<div class="solution"><strong>${q.kind==='mcq'?'Answer '+String.fromCharCode(65+q.correct):'Original marking points'} · ${q.marks} ${q.marks===1?'mark':'marks'}</strong><ul>${q.scheme.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${q.kind!=='mcq'?`<label style="display:block;margin-top:13px">Your marks (0–${q.marks}): <select data-selfmark="${q.id}" aria-label="Self-mark question ${q.id}">${Array.from({length:q.marks+1},(_,i)=>`<option value="${i}" ${progress.results[q.id]?.score===i?'selected':''}>${i}</option>`).join('')}</select> <button class="btn small" data-action="savescore" data-id="${q.id}">Save marks</button></label>`:''}</div>`}
function questionCard(q,{test=false,index=0}={}){const a=progress.activeTest,ans=test?a?.answers[q.id]:state.chosen[q.id],revealed=!test&&!!state.revealed[q.id];return `<article class="card qcard" id="${q.id}"><div class="q-meta">${pill(q.topic)}${pill(q.level==='HL'?'HL':'SL + HL',q.level==='HL'?'hl':'soft')}${pill(q.paper,'soft')}${pill(q.difficulty,'soft')}${pill(q.marks+' '+(q.marks===1?'mark':'marks'))}<span class="qid">${test?'QUESTION '+(index+1):q.id}</span></div><h3>${esc(q.text)}</h3>${q.kind==='mcq'?`<div class="choices">${q.options.map((op,i)=>`<button class="choice ${ans===i?'selected':''} ${revealed&&i===q.correct?'correct':''} ${revealed&&ans===i&&i!==q.correct?'incorrect':''}" data-choice="${q.id}" data-opt="${i}" data-test="${test?1:0}" aria-pressed="${ans===i}"><span>${String.fromCharCode(65+i)}</span><span>${esc(op)}</span></button>`).join('')}</div>`:`<label class="question-note" for="answer-${q.id}">Write your answer before viewing the marking points.</label><textarea class="response" id="answer-${q.id}" data-draft="${q.id}" data-test="${test?1:0}" placeholder="Explain your reasoning or show your calculation…" maxlength="8000">${esc(test?(a?.answers[q.id]||''):(progress.drafts[q.id]||''))}</textarea>`}${test?'':`<div class="qcontrols"><div class="row"><button class="btn small" data-action="reveal" data-id="${q.id}">${revealed?'Hide marking points':'Show marking points'}</button><button class="btn small" data-askq="${q.id}">✦ Help me understand</button></div><button class="text-btn" data-action="star" data-id="${q.id}">${progress.stars[q.id]?'★ Saved':'☆ Save'}</button></div>${revealed?solution(q):''}`}</article>`}
function bank(){const a=pool();return `${head('PRACTISE WITH PURPOSE','Question bank',`Choose topics from the full ${progress.level} syllabus. These ${questions().length} independently written exam-style questions include explained solutions and marking points. They are not copied official IB past-paper questions.`)}<div class="card filter-card">${select('topic','Topic',[['all','All topics'],...topics().map(t=>[t.id,t.id+' '+t.name])],state.filters.topic)}${select('level','Level',[['all',progress.level==='SL'?'SL only':'All HL content'],['SL','Shared SL + HL'],...(progress.level==='HL'?[['HL','HL extensions']]:[])],state.filters.level)}${select('paper','Paper',[['all','All paper types'],['Paper 1A','Paper 1A · MCQ'],['Paper 1B','Paper 1B · Data'],['Paper 2','Paper 2 · Written']],state.filters.paper)}${select('difficulty','Difficulty',[['all','All difficulties'],['Easy','Easy'],['Medium','Medium'],['Hard','Hard']],state.filters.difficulty)}${select('status','Progress',[['all','All questions'],['unanswered','Not attempted'],['review','Needs revision'],['saved','Saved']],state.filters.status)}</div><div class="row between" style="margin-bottom:15px;font-size:11px;color:#91a3ac"><span><b style="color:#527580">${a.length} questions</b> · ${a.reduce((n,q)=>n+q.marks,0)} marks</span><button class="text-btn" data-action="clearfilters">Clear filters</button></div><div class="bank-layout"><div>${a.length?a.slice(0,state.limit).map(q=>questionCard(q)).join(''):'<div class="card empty"><h3>No matching questions</h3><p>Try widening the topic or paper filters.</p></div>'}${a.length>state.limit?'<button class="btn" data-action="more">Load more questions →</button>':''}</div><aside class="sticky"><div class="card bank-side"><span class="eyebrow">STUDY INTENTIONALLY</span><h3 style="margin-top:12px">Make the next test count.</h3><p>Choose topics and set your time limit. Mark your answers and find what needs another look.</p><a href="#test" class="btn primary small">Build a target test →</a></div><div class="card bank-side" style="margin-top:15px"><h3>Authentic IB papers</h3><p>Genuine specimen and released examination papers are in their own SL and HL library.</p><a href="#papers" class="text-btn">Open official papers ↗</a></div></aside></div>`}
function buildTest(){const active=progress.activeTest;return `${head('FOCUS ON YOUR NEXT STEP','Build a target test','Choose the topics you need, the question style and a time limit. Your test uses the original question bank. Results show marks and topics to revisit; they do not predict an official IB grade.')} ${active?`<div class="notice"><strong>You have a test in progress.</strong> ${active.ids.length} questions, started ${new Date(active.startedAt).toLocaleDateString()}.<div class="row" style="margin-top:10px"><a href="#session" class="btn primary small">Resume test →</a><button class="btn small" data-action="discardtest">Discard unfinished test</button></div></div>`:''}<form id="testForm" class="test-grid"><div class="card panel"><div class="row between" style="margin-bottom:20px"><h2 style="font-size:18px;margin:0">1. Select your topics</h2><div class="row"><button type="button" class="text-btn" data-action="selectall">Select all</button><button type="button" class="text-btn" data-action="selectnone">Clear</button></div></div>${[...new Set(topics().map(t=>t.group))].map(g=>`<section class="test-group"><h3>${esc(g)}</h3>${topics().filter(t=>t.group===g).map(t=>`<label class="topic-check"><input type="checkbox" name="topics" value="${t.id}" ${state.testSelection.includes(t.id)?'checked':''}>${t.id} · ${esc(t.name)} <span class="pill soft">${questions().filter(q=>q.topic===t.id).length}</span></label>`).join('')}</section>`).join('')}</div><div class="card panel sticky"><h2 style="font-size:18px">2. Shape your test</h2><div class="test-fields"><div class="field"><label for="testPaper">Paper style</label><select id="testPaper" name="paper"><option value="all">Mixed exam-style</option><option>Paper 1A</option><option>Paper 1B</option><option>Paper 2</option></select></div><div class="field"><label for="testDiff">Difficulty</label><select id="testDiff" name="difficulty"><option value="all">Mixed difficulty</option><option>Easy</option><option>Medium</option><option>Hard</option></select></div><div class="field"><label for="testCount">Number of questions</label><input id="testCount" name="count" type="number" min="1" max="40" value="10" required></div><div class="field"><label for="testMinutes">Time limit (minutes)</label><input id="testMinutes" name="minutes" type="number" min="1" max="180" value="20" required></div><div class="field"><label for="testTarget">Target mark percentage</label><input id="testTarget" name="target" type="number" min="1" max="100" value="70" required></div><button class="btn primary" type="submit">Create my test →</button><p style="font-size:10px;color:#9bafb5;margin:0">If the selected pool is smaller than the requested count, we use the available questions and tell you. No duplicate filler questions.</p></div></div></form>`}
function shuffled(a){const out=[...a];for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function startTest(e){e.preventDefault();const f=new FormData(e.target),ts=f.getAll('topics');if(!ts.length)return toast('Choose at least one topic.');if(progress.activeTest)return toast('Resume or discard your current test first.');const count=Math.min(40,Math.max(1,Number(f.get('count')))),mins=Math.min(180,Math.max(1,Number(f.get('minutes'))));const pool=questions().filter(q=>ts.includes(q.topic)&&(f.get('paper')==='all'||q.paper===f.get('paper'))&&(f.get('difficulty')==='all'||q.difficulty===f.get('difficulty')));if(!pool.length)return toast('No questions match those settings. Choose another paper or difficulty.');const a=shuffled(pool).slice(0,count);progress.activeTest={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),level:progress.level,ids:a.map(q=>q.id),topics:ts,startedAt:Date.now(),deadline:Date.now()+mins*60000,minutes:mins,target:Number(f.get('target')),answers:{}};save();if(a.length<count)toast(`Created a ${a.length}-question test: that is the available pool.`);location.hash='session'}
function session(){const a=progress.activeTest;if(!a)return `${head('TARGET TEST','No active test','Create a test to start practising.')}<a href="#test" class="btn primary">Build a test →</a>`;return `${crumb(['Target test','In progress'])}<span class="eyebrow">${a.level} · ORIGINAL PRACTICE</span><h1>Your focused practice session</h1><p class="lede">Answer before the timer finishes. The timer continues if you leave the page. MCQs mark automatically; written answers need self-marking after submission.</p><div class="timebar"><div><small>${a.ids.length} QUESTIONS · ${a.ids.reduce((n,id)=>n+(byQ(id)?.marks||0),0)} MARKS · TARGET ${a.target}%</small><div>Take your time with the reasoning.</div></div><div><small>TIME REMAINING</small><div><strong id="timer">${timeRemaining(a)}</strong></div></div><button class="btn light" data-action="submittest">Finish test →</button></div>${a.ids.map((id,i)=>questionCard(byQ(id),{test:true,index:i})).join('')}<div class="row between"><span style="color:#9bafb8;font-size:11px">Answers save automatically in this browser.</span><button class="btn primary" data-action="submittest">Finish & review →</button></div>`}
function timeRemaining(a){const sec=Math.max(0,Math.ceil((a.deadline-Date.now())/1000));return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
function finishTest(auto=false){const a=progress.activeTest;if(!a)return;const scores={};a.ids.forEach(id=>{const q=byQ(id);if(q.kind==='mcq'){scores[id]=a.answers[id]===q.correct?q.marks:0;progress.results[id]={score:scores[id],at:Date.now()}}});progress.tests.unshift({...a,scores,finishedAt:Date.now(),timedOut:auto});progress.tests=progress.tests.slice(0,20);progress.activeTest=null;save();location.hash='result/'+a.id;if(auto)toast('Time is up. Your answers were saved for review.');}
function result(){const r=progress.tests.find(t=>t.id===state.id);if(!r)return missing();const max=r.ids.reduce((n,id)=>n+(byQ(id)?.marks||0),0),pending=r.ids.filter(id=>r.scores[id]===undefined),score=Object.values(r.scores).reduce((n,s)=>n+s,0),pct=Math.round(score/max*100),complete=!pending.length;const lowTopics=[...new Set(r.ids.filter(id=>(r.scores[id]??0)<byQ(id).marks).map(id=>byQ(id).topic))];return `${head('TEST REVIEW',complete?'Make your next step clearer.':'Review your written answers.',`Your original ${r.level} practice set · ${r.ids.length} questions · Target ${r.target}%. ${r.timedOut?'The test ended when the timer expired.':''}`)}<div class="card panel"><div class="row between"><div><span class="eyebrow">${complete?'FINAL PRACTICE SCORE':'PROVISIONAL MARKS'}</span><div class="score-big">${score} <span style="font-size:20px;letter-spacing:0;color:#94b1a4">/ ${max}</span></div><p style="font-size:12px;color:#8a9f9a;margin:8px 0">${complete?`${pct}% · ${pct>=r.target?'Target reached ✓':'Below your target — use the review below.'}`:`${pending.length} written answers still need self-marking. Your percentage is not final.`}</p></div><div class="row"><a class="btn" href="#test">Build another test</a><button class="btn" data-action="print">Print review</button></div></div></div><div class="section-head"><h2>Questions & worked marking points</h2></div>${r.ids.map((id,i)=>{const q=byQ(id),ans=r.answers[id];return `<article class="card qcard"><div class="q-meta">${pill('Q'+(i+1))}${pill(q.topic)}${pill(q.marks+' marks','soft')}</div><h3>${esc(q.text)}</h3><div class="notice" style="margin:12px 0"><strong>Your answer:</strong> ${q.kind==='mcq'?(ans===undefined?'Unanswered':String.fromCharCode(65+ans)+'. '+esc(q.options[ans])):esc(ans||'Unanswered')}</div><div class="solution"><strong>${q.kind==='mcq'?'Correct: '+String.fromCharCode(65+q.correct):'Original marking points'}</strong><ul>${q.scheme.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>${q.kind!=='mcq'?`<label class="row" style="margin-top:15px;font-size:11px;color:#7e9b8f">Self-awarded marks out of ${q.marks}<select class="test-inputscore" data-testscore="${r.id}" data-q="${id}" aria-label="Marks for question ${i+1}"><option value="">Choose</option>${Array.from({length:q.marks+1},(_,j)=>`<option value="${j}" ${r.scores[id]===j?'selected':''}>${j}</option>`).join('')}</select></label>`:`<p style="font-size:11px;color:#6c9278;margin-top:13px">Automatically marked: ${r.scores[id]} / ${q.marks}</p>`}<button class="text-btn" style="margin-top:15px" data-askq="${id}">✦ Explain this question</button></article>`}).join('')}${lowTopics.length?`<div class="section-head"><h2>Revisit these topics</h2></div><div class="report-list">${lowTopics.map(id=>`<a href="#topic/${id}">${id} · ${esc(byTopic(id)?.name||'')} →</a>`).join('')}</div>`:''}`}
function papers(){const level=progress.level,resources=PAPERS.filter(p=>p.level===level||p.level==='both');return `${head('AUTHENTIC IB RESOURCES',`${level} past papers & specimen papers`,`The ${level} collection links to the IB’s own released documents. Switch the course selector for ${level==='HL'?'SL':'HL'}. Specimen papers are assessment examples, not past examination sessions. Official paid content is not republished here.`)}<div class="notice"><strong>Current syllabus only.</strong> The specimen bundle and released May 2025 samples match the first-assessment-2025 course. Not every session is publicly released. Mark schemes are linked only where a verified official source exists; some PDF viewers may ignore the paper’s page anchor.</div><div class="paper-grid">${resources.map(p=>`<article class="card paper-card"><div class="row">${pill(p.level==='both'?'SL + HL':p.level)}${pill(p.kind==='specimen'?'SPECIMEN':p.kind==='questionbank'?'LICENSED QUESTIONBANK':'ACTUAL EXAM SAMPLE',p.kind==='specimen'?'soft':'orange')}</div><h3>${esc(p.title)}</h3><p>${esc(p.notes||p.session||'Official International Baccalaureate resource.')}</p><div class="row"><a class="btn primary small" href="${safeURL(p.url)}" target="_blank" rel="noopener noreferrer">${p.kind==='questionbank'?'Open IB Questionbank':'Open official paper'} ↗</a>${p.markschemeUrl?`<a class="btn small" href="${safeURL(p.markschemeUrl)}" target="_blank" rel="noopener noreferrer">Official mark scheme ↗</a>`:''}</div>${!p.markschemeUrl&&p.kind!=='questionbank'?'<p class="question-note" style="margin:12px 0 0">A separate official mark scheme has not been verified for this sample.</p>':''}</article>`).join('')}</div><div class="notice"><strong>The question bank is different.</strong> Built-in interactive questions and marking points are original independent practice. To work with authentic licensed IB exam questions, use the official IB Questionbank.</div>`}
function skills(){return `${head('THE OTHER HALF OF UNDERSTANDING','Practical, data & inquiry skills','The uploaded syllabus includes tools for experimental techniques, technology and mathematics, plus the inquiry process. Study these alongside the content; they support Paper 1B, investigations and explanations.')}<div class="skills-grid">${SKILLS.map(s=>`<section class="card skill-card"><span class="eyebrow">${esc(s.tag)}</span><h3 style="margin-top:10px">${esc(s.title)}</h3><p>${esc(s.text)}</p><ul>${s.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="skill-example">${esc(s.example)}</div></section>`).join('')}</div><div class="notice"><strong>Assessment orientation (uploaded guide).</strong> Written examinations contribute 80% and the scientific investigation 20%. SL Paper 1 is 1½ hours and Paper 2 is 1½ hours; HL Paper 1 is 2 hours and Paper 2 is 2½ hours. Paper 1 contains 1A multiple-choice and 1B data/experimental questions. Use the guide and school instructions for actual examination arrangements.</div>`}
function dashboard(){const q=questions(),results=q.filter(x=>progress.results[x.id]),score=results.reduce((n,x)=>n+progress.results[x.id].score,0),max=results.reduce((n,x)=>n+x.marks,0);return `${head('YOUR STUDY DASHBOARD','Progress you can build on.','Track concepts studied, practice marks and target tests. Local mode saves in this browser. Sign in and use the account’s cloud sync controls to transfer progress between devices.')}<div class="grid"><div class="card stat"><span class="stat-icon">✓</span><div><strong>${completed()}/${lessons().length}</strong><small>LESSONS REVIEWED</small></div></div><div class="card stat"><span class="stat-icon">▦</span><div><strong>${results.length}</strong><small>QUESTIONS MARKED</small></div></div><div class="card stat"><span class="stat-icon">◔</span><div><strong>${max?Math.round(score/max*100):0}%</strong><small>OF ATTEMPTED PRACTICE MARKS</small></div></div></div><div class="section-head"><h2>Course progress</h2><button class="text-btn" data-action="account">${state.session?'Sync with your account ↗':'Set up cloud sync ↗'}</button></div><div class="grid two">${topics().map(t=>`<div class="card progress-topic"><div class="row between"><strong>${t.id} · ${esc(t.name)}</strong><small>${topicPct(t)}%</small></div>${bars(topicPct(t))}<a href="#topic/${t.id}" style="font-size:10px">Continue →</a></div>`).join('')}</div><div class="section-head"><h2>Target test history</h2></div><div class="report-list">${progress.tests.length?progress.tests.map(t=>`<a href="#result/${t.id}">${t.level} · ${t.ids.length} questions · ${new Date(t.finishedAt).toLocaleDateString()} · ${t.ids.some(id=>t.scores[id]===undefined)?'Needs self-marking':'Reviewed'} →</a>`).join(''):'<div class="card panel"><p style="color:#94a9b2;font-size:12px">No tests completed yet. Build a focused practice session to begin.</p><a href="#test" class="btn primary small">Create a target test →</a></div>'}</div><div class="section-head"><h2>Keep your study record</h2></div><div class="card panel"><p style="font-size:12px;color:#7c96a1">Export a backup before changing devices or clearing browser data. Import replaces this browser’s current progress after confirmation. Account sessions and AI conversations are not exported.</p><div class="row"><button class="btn" data-action="export">Export progress</button><label class="btn export-label">Import backup<input type="file" id="importProgress" accept="application/json,.json"></label><button class="btn danger" data-action="resetprogress">Reset local progress</button></div></div>`}
function searchView(){const q=state.search.trim().toLowerCase(),ss=lessons().filter(s=>[s.id,s.title,s.summary,...s.explain].join(' ').toLowerCase().includes(q));return `${head('FIND YOUR NEXT CONCEPT',`Results for “${state.search}”`,`${ss.length} lesson matches in your ${progress.level} course.`)}<div class="lessons">${ss.length?ss.map(s=>`<a class="lesson-link" href="#lesson/${s.id}"><span class="lesson-code">${s.id}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p></div><span class="arrow">Open →</span></a>`).join(''):'<div class="card empty">Try a topic name, formula or syllabus code.</div>'}</div>`}
function missing(){return `<div class="card empty"><h1>We couldn’t find that page.</h1><p>Choose a topic from your syllabus to continue.</p><a class="btn primary" href="#syllabus">Open revision notes</a></div>`}
function render(){navUI();const routes={home,syllabus,topic,lesson,bank,test:buildTest,session,result,papers,skills,progress:dashboard,search:searchView};$('#view').innerHTML=(routes[state.page]||missing)();document.title=(state.page==='lesson'?byLesson(state.id)?.title+' · ':'')+'Chemistry Atlas · IB '+progress.level;}
function route(){const hash=decodeURIComponent(location.hash.slice(1)),[page,id]=hash.split('/');state.page=page||'home';state.id=id||'';state.limit=18;render();closeMenu();scrollTo({top:0,behavior:'instant'})}
function rerender(){const y=scrollY;render();scrollTo(0,y)}
function closeMenu(){$('#sidebar').classList.remove('open');$('#overlay').classList.remove('show')}
function lessonContext(s){return `${s.id} (${s.hl?'HL extension':'SL and HL'}): ${s.title}\n${s.summary}\n${s.explain.join('\n')}\nWorked example: ${s.example.q}\n${s.example.steps.join('\n')}\nAnswer: ${s.example.answer}`}
function setChatContent(){const chat=$('#chat');chat.replaceChildren();state.messages.forEach(m=>{const div=document.createElement('div');div.className='chat-message '+(m.role==='user'?'user':'');div.textContent=m.content;chat.append(div)});chat.scrollTop=chat.scrollHeight;}
function openTutor(context='',label='General chemistry questions'){state.tutorContext=context;$('#tutorContext').textContent='Study context: '+label;const chat=$('#chat');if(!state.cloudReady){chat.innerHTML='<div class="tutor-note"><strong>AI tutor integration is ready for setup.</strong><br>To receive AI answers, the website owner must connect Supabase and deploy the tutor function with a server-held model API key. See DEPLOYMENT.md in the GitHub package. This preview does not simulate AI answers.<br><br>You can still read every lesson, watch videos, practise questions and build tests.</div>';}else if(!state.session){chat.innerHTML='<div class="tutor-note">Sign in with your email code before using the AI tutor. Your current lesson or question will be supplied as context when you send a message.</div>';}else setChatContent();$('#sendTutor').disabled=!state.cloudReady||!state.session;$('#tutorInput').disabled=!state.cloudReady||!state.session;$('#tutorDialog').showModal();}
async function account(){const body=$('#accountBody');if(!state.cloudReady){body.innerHTML='<div class="auth-status"><strong>Local study mode is working.</strong></div><p>Cloud login needs the owner’s Supabase configuration. It has not been connected in this package. Your study progress currently saves in this browser.</p><p>The included setup guide explains how to enable real email-code accounts, per-user saved progress and the AI tutor on your GitHub-hosted site.</p><div class="setup-link">Open <strong>DEPLOYMENT.md</strong> in the source ZIP.</div><div class="row" style="margin-top:18px"><button class="btn" data-close="accountDialog">Keep studying</button><button class="btn primary" data-action="export">Export my progress</button></div>';}
else if(state.session){body.innerHTML=`<p>Signed in as <strong>${esc(state.session.user?.email||'student')}</strong></p><div class="auth-status">Cloud sync is manual so that one device never silently overwrites another. Choose the direction below.</div><div class="row"><button class="btn primary" data-action="uploadcloud">Save this device to cloud</button><button class="btn" data-action="downloadcloud">Load cloud progress</button></div><p style="margin-top:16px">Saving replaces your account’s cloud document. Loading replaces this browser’s study record after confirmation. On a shared computer, sign out and clear local progress before leaving.</p><button class="btn" data-action="signout">Sign out & clear this device</button>`;}
else body.innerHTML='<p>Receive a one-time sign-in code by email. Passwords are not stored in this website.</p><form id="loginForm" class="auth-form"><div class="field"><label for="loginEmail">Email address</label><input id="loginEmail" type="email" autocomplete="email" required placeholder="you@example.com"></div><button class="btn primary" type="submit">Email a sign-in code →</button></form><form id="verifyForm" class="auth-form" style="margin-top:20px" hidden><div class="field"><label for="loginCode">Code from your email</label><input id="loginCode" inputmode="numeric" autocomplete="one-time-code" required maxlength="10"></div><button class="btn primary" type="submit">Verify code & sign in</button></form><p id="authMessage" style="margin-top:13px;font-size:11px"></p>';if(!$('#accountDialog').open)$('#accountDialog').showModal();}
function validatedProgress(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw new Error('Invalid study record.');const out={level:raw.level==='SL'?'SL':'HL',done:{},results:{},stars:{},drafts:{},tests:[],activeTest:null};for(const s of LESSONS)if(raw.done?.[s.id]===true)out.done[s.id]=true;for(const q of QUESTIONS){const r=raw.results?.[q.id];if(r&&Number.isInteger(r.score)&&r.score>=0&&r.score<=q.marks)out.results[q.id]={score:r.score,at:Number(r.at)||Date.now()};if(raw.stars?.[q.id]===true)out.stars[q.id]=true;if(typeof raw.drafts?.[q.id]==='string')out.drafts[q.id]=raw.drafts[q.id].slice(0,8000);}if(Array.isArray(raw.tests))out.tests=raw.tests.filter(t=>t&&typeof t.id==='string'&&/^[A-Za-z0-9-]{1,80}$/.test(t.id)&&Array.isArray(t.ids)&&t.ids.length<=40&&t.ids.every(id=>!!byQ(id))&&t.answers&&typeof t.answers==='object'&&t.scores&&typeof t.scores==='object'&&Object.entries(t.scores).every(([id,v])=>t.ids.includes(id)&&Number.isInteger(v)&&v>=0&&v<=byQ(id).marks)).slice(0,20);return out;}
function resetLocal(){Object.assign(progress,{level:progress.level,done:{},results:{},stars:{},drafts:{},tests:[],activeTest:null});save();state.chosen={};state.revealed={};}
function exportProgress(){const data=new Blob([JSON.stringify({format:'chemistry-atlas-progress',version:1,exportedAt:new Date().toISOString(),progress},null,2)],{type:'application/json'}),u=URL.createObjectURL(data),a=document.createElement('a');a.href=u;a.download='Chemistry_Atlas_Progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Progress backup exported.');}
async function click(e){const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const closer=e.target.closest('[data-close]');if(closer){document.getElementById(closer.dataset.close)?.close();return;}const banktopic=e.target.closest('[data-banktopic]');if(banktopic){state.filters.topic=banktopic.dataset.banktopic;state.filters.level='all';state.filters.status='all';if(state.page==='bank')rerender();}const asklesson=e.target.closest('[data-asklesson]');if(asklesson){const s=byLesson(asklesson.dataset.asklesson);state.messages=[];openTutor(lessonContext(s),s.id+' · '+s.title);return;}const askq=e.target.closest('[data-askq]');if(askq){const q=byQ(askq.dataset.askq);state.messages=[];openTutor(`${q.topic} ${q.paper}\n${q.text}\n${(q.options||[]).join('\n')}\nOriginal marking guidance:\n${q.scheme.join('\n')}`,q.id+' · '+q.topic);return;}const choice=e.target.closest('[data-choice]');if(choice){const id=choice.dataset.choice,op=Number(choice.dataset.opt),q=byQ(id);if(choice.dataset.test==='1'){if(progress.activeTest){progress.activeTest.answers[id]=op;save();}}else{state.chosen[id]=op;state.revealed[id]=true;progress.results[id]={score:op===q.correct?q.marks:0,at:Date.now()};save();}rerender();return;}const a=e.target.closest('[data-action]');if(!a)return;const id=a.dataset.id;try{switch(a.dataset.action){case'done':progress.done[id]=!progress.done[id];save();rerender();toast(progress.done[id]?'Lesson marked as studied.':'Lesson unmarked.');break;case'print':print();break;case'reveal':state.revealed[id]=!state.revealed[id];rerender();break;case'star':progress.stars[id]=!progress.stars[id];save();rerender();break;case'more':state.limit+=18;rerender();break;case'savescore':{const inp=$(`[data-selfmark="${id}"]`);progress.results[id]={score:Number(inp.value),at:Date.now()};save();toast('Practice marks saved.');break;}case'clearfilters':Object.keys(state.filters).forEach(k=>state.filters[k]='all');rerender();break;case'selectall':$$('#testForm [name="topics"]').forEach(c=>c.checked=true);break;case'selectnone':$$('#testForm [name="topics"]').forEach(c=>c.checked=false);break;case'discardtest':if(confirm('Discard this unfinished test?')){progress.activeTest=null;save();rerender();}break;case'submittest':if(confirm('Finish this test and review your answers?'))finishTest();break;case'export':exportProgress();break;case'resetprogress':if(confirm('Clear the local study record? Export first if you want a backup. This does not delete your cloud document.')){resetLocal();rerender();toast('Local progress reset.');}break;case'setHL':progress.level='HL';save();rerender();break;case'account':account();break;case'uploadcloud':if(confirm('Replace your cloud study document with this device’s progress?')){a.disabled=true;await AtlasCloud.saveProgress(progress);toast('Saved this device’s progress to your account.');a.disabled=false;}break;case'downloadcloud':{a.disabled=true;const row=await AtlasCloud.loadProgress();a.disabled=false;if(!row){toast('Your account has no saved progress yet. Save this device first.');break;}const incoming=validatedProgress(row.payload);if(confirm('Replace this browser’s progress with your cloud document?')){Object.assign(progress,incoming);save();rerender();toast('Cloud progress loaded.');}break;}case'signout':await AtlasCloud.signOut();state.session=null;resetLocal();state.messages=[];$('#tutorInput').value='';$('#accountDialog').close();rerender();toast('Signed out. Local study record cleared from this device.');break;}}catch(error){a.disabled=false;toast(error.message||'That action could not be completed.');}}
async function submit(e){if(e.target.id==='testForm')return startTest(e);if(e.target.id==='loginForm'){e.preventDefault();const email=$('#loginEmail').value.trim(),b=e.target.querySelector('button');b.disabled=true;try{await AtlasCloud.signIn(email);$('#verifyForm').hidden=false;$('#authMessage').textContent='Check your email for the code. The owner must configure email delivery and the code template.';}catch(err){$('#authMessage').textContent=err.message;}finally{b.disabled=false}return;}if(e.target.id==='verifyForm'){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{state.session=await AtlasCloud.verifyOtp($('#loginEmail').value.trim(),$('#loginCode').value);await account();navUI();toast('Signed in. Choose cloud sync direction in your account.');}catch(err){$('#authMessage').textContent=err.message;}finally{b.disabled=false}return;}if(e.target.id==='tutorForm'){e.preventDefault();if(!state.cloudReady||!state.session)return;const input=$('#tutorInput'),msg=input.value.trim();if(!msg)return;state.messages.push({role:'user',content:msg});input.value='';setChatContent();$('#sendTutor').disabled=true;try{const answer=await AtlasCloud.ask(state.messages.slice(-8),state.tutorContext);state.messages.push({role:'assistant',content:String(answer||'No answer was returned.')});setChatContent();}catch(err){const div=document.createElement('div');div.className='chat-message error';div.textContent=err.message;$('#chat').append(div);}finally{$('#sendTutor').disabled=false;}return;}}
async function change(e){if(e.target.id==='level'){if(progress.activeTest){e.target.value=progress.level;return toast('Finish or discard the current test before switching level.');}progress.level=e.target.value;state.filters.level='all';if(!topics().some(t=>t.id===state.filters.topic))state.filters.topic='all';save();rerender();return;}if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;state.limit=18;rerender();return;}if(e.target.dataset.testscore){const r=progress.tests.find(t=>t.id===e.target.dataset.testscore),id=e.target.dataset.q;if(e.target.value==='')delete r.scores[id];else{r.scores[id]=Number(e.target.value);progress.results[id]={score:Number(e.target.value),at:Date.now()}}save();rerender();return;}if(e.target.id==='importProgress'){const file=e.target.files[0];if(!file)return;if(file.size>2000000)return toast('Backup is too large.');try{const data=JSON.parse(await file.text());if(data.format!=='chemistry-atlas-progress')throw new Error('This is not a Chemistry Atlas progress backup.');const incoming=validatedProgress(data.progress);if(confirm('Replace local progress with this backup?')){Object.assign(progress,incoming);save();rerender();toast('Backup imported. Unfinished sessions are not imported.');}}catch(err){toast(err.message)}return;}}
function inputs(e){if(e.target.dataset.draft){const id=e.target.dataset.draft,val=e.target.value.slice(0,8000);if(e.target.dataset.test==='1'&&progress.activeTest)progress.activeTest.answers[id]=val;else progress.drafts[id]=val;save();}}
async function init(){document.addEventListener('click',click);document.addEventListener('submit',submit);document.addEventListener('change',change);document.addEventListener('input',inputs);window.addEventListener('hashchange',route);$('#menu').addEventListener('click',()=>{$('#sidebar').classList.toggle('open');$('#overlay').classList.toggle('show')});$('#overlay').addEventListener('click',closeMenu);$('#accountBtn').addEventListener('click',account);$('#tutorBtn').addEventListener('click',()=>{if(state.page==='lesson'){const s=byLesson(state.id);openTutor(s?lessonContext(s):'',s?.title||'General chemistry')}else openTutor();});$('#sideTutor').addEventListener('click',()=>openTutor());$('#search').addEventListener('input',e=>{state.search=e.target.value.trim();if(state.search.length>1){state.page='search';render();}else if(!state.search)route();});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')closeMenu()});route();setInterval(()=>{const a=progress.activeTest;if(a){if(Date.now()>=a.deadline){finishTest(true);}else{const timer=$('#timer');if(timer)timer.textContent=timeRemaining(a);}}},1000);window.addEventListener('atlas-auth-change',async e=>{if(!e.detail.signedIn)state.session=null;navUI()});if(window.AtlasCloud)try{state.session=await AtlasCloud.init(window.ATLAS_CONFIG||{});state.cloudReady=AtlasCloud.isConfigured();navUI();}catch(err){state.cloudReady=AtlasCloud.isConfigured();toast('Cloud session: '+err.message)}}
init();
